            - type: presence
              target: "option_a.txt"
            - type: presence
              target: "option_b.txt"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let check = config.steps["complex"].execution.check.as_ref().unwrap();
