        let check: Check = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(check, Check::Presence { .. }));
        assert_eq!(check.type_name(), "presence");
    }

    #[test]
    fn command_succeeds_alias_parses_as_execution() {
        let yaml = r#"
type: command_succeeds
command: "ruby --version"
"#;
        let check: Check = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(check, Check::Execution { .. }));
        assert_eq!(check.type_name(), "execution");
    }

    #[test]
    fn prompt_if_complete_alias_parses_as_prompt_on_rerun() {
        let yaml = r#"
command: "cargo build"
prompt_if_complete: false
"#;
        let step: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(step.behavior.prompt_on_rerun, Some(false));
    }

    #[test]
    fn watches_field_parses_and_migrates_to_change_checks() {
        let yaml = r#"
steps:
  build:
    command: "cargo build"
    watches:
      - Cargo.toml
      - Cargo.lock
"#;
        let mut config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let warnings = config.migrate_deprecated_fields();

        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("'watches' is deprecated"));

        let step = &config.steps["build"];
        assert_eq!(step.execution.checks.len(), 2);
        assert!(step.watches.is_empty());

        // Verify the checks are change-type with the right targets
        for (i, expected_target) in ["Cargo.toml", "Cargo.lock"].iter().enumerate() {
            match &step.execution.checks[i] {
                Check::Change { target, .. } => assert_eq!(target, expected_target),
                other => panic!("Expected Change check, got {:?}", other),
            }
        }
    }

    #[test]
    fn watches_migration_merges_with_existing_checks() {
        let yaml = r#"
steps:
  build:
    command: "cargo build"
    checks:
      - type: presence
        target: "target/debug/bivvy"
    watches:
      - Cargo.toml
"#;
        let mut config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        config.migrate_deprecated_fields();

        let step = &config.steps["build"];
        assert_eq!(step.execution.checks.len(), 2);
        assert!(matches!(step.execution.checks[0], Check::Presence { .. }));
        assert!(matches!(step.execution.checks[1], Check::Change { .. }));
    }

    #[test]
    fn unknown_settings_field_is_captured() {
        let yaml = r#"
settings:
  paralell: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(
            !config.settings._unknown.is_empty(),
            "Typo 'paralell' should be captured as unknown"
        );
        assert!(config.settings._unknown.contains_key("paralell"));
    }

    #[test]
    fn unknown_step_field_is_captured() {
        let yaml = r#"
steps:
  test:
    comand: "echo test"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["test"];
        assert!(
            !step._unknown.is_empty(),
            "Typo 'comand' should be captured as unknown"
        );
        assert!(step._unknown.contains_key("comand"));
    }

    #[test]
    fn valid_config_has_no_unknown_fields() {
        let yaml = r#"
app_name: Test
settings:
  parallel: true
  defaults:
    output: quiet
steps:
  test:
    command: "echo test"
    retry: 2
workflows:
  default:
    steps: [test]
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.settings._unknown.is_empty());
        assert!(config.steps["test"]._unknown.is_empty());
    }

    #[test]
    fn check_unknown_fields_returns_error_for_settings_typo() {
        let yaml = r#"
settings:
  paralell: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let result = config.check_unknown_fields();
        assert!(result.is_err());
        let fields = result.unwrap_err();
        assert!(fields.iter().any(|f| f.contains("paralell")));
    }

    #[test]
    fn check_unknown_fields_returns_error_for_step_typo() {
        let yaml = r#"
steps:
  test:
    comand: "echo test"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let result = config.check_unknown_fields();
        assert!(result.is_err());
        let fields = result.unwrap_err();
        assert!(fields.iter().any(|f| f.contains("comand")));
        assert!(fields.iter().any(|f| f.contains("test")));
    }

    #[test]
    fn check_unknown_fields_passes_for_valid_config() {
        let yaml = r#"
app_name: Test
settings:
  parallel: true
steps:
  hello:
    command: "echo hello"
workflows:
  default:
    steps: [hello]
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.check_unknown_fields().is_ok());
    }
}

