    #[test]
    fn effective_kind_falls_back_to_url_detection() {
        let source = TemplateSource {
            kind: None,
            url: "git@github.com:org/repo.git".to_string(),
            git_ref: None,
            path: None,
            priority: 100,
            timeout: 30,
            cache: None,
            auth: None,
