/// Validate a configuration and return all errors.
///
/// This function collects all validation errors rather than stopping
/// at the first one, allowing users to fix multiple issues at once.
pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    errors.extend(validate_unknown_fields(config));
    errors.extend(validate_vars(config));
    errors.extend(validate_steps(config));
    errors.extend(validate_workflows(config));
    errors.extend(validate_dependencies(config));

    errors
}

/// Flag fields that were not recognized during deserialization.
///
/// `Settings` and `StepConfig` use `#[serde(flatten)]` which prevents
/// serde's `deny_unknown_fields` from working. Unrecognized keys are
/// captured into `_unknown` catch-all maps instead, and this function
/// turns them into validation errors.
fn validate_unknown_fields(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    for key in config.settings._unknown.keys() {
        errors.push(ValidationError {
            rule: "unknown-field".to_string(),
            message: format!("Unknown field '{}' in settings", key),
            step: None,
            workflow: None,
        });
    }

    for (step_name, step) in &config.steps {
        for key in step._unknown.keys() {
            errors.push(ValidationError {
                rule: "unknown-field".to_string(),
                message: format!("Unknown field '{}' in step '{}'", key, step_name),
                step: Some(step_name.clone()),
                workflow: None,
            });
        }
    }

    errors
}

